const MIN_FULL_JOB_TEXT = 200;
const MAX_FULL_JOB_TEXT = 15000;

const decodeHtml = (s) =>
  String(s || "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");

const stripTags = (html) =>
  String(html || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<!--[\s\S]*?-->/g, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const isJobPostingType = (value) => {
  if (value === "JobPosting") return true;
  if (Array.isArray(value)) return value.includes("JobPosting");
  return false;
};

const extractJsonLdJobPostingDescription = (html) => {
  const blocks =
    String(html || "").match(
      /<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi,
    ) || [];

  for (const block of blocks) {
    const inner = block.replace(/^<script[^>]*>/i, "").replace(/<\/script>$/i, "").trim();
    try {
      const parsed = JSON.parse(inner);
      const nodes = Array.isArray(parsed) ? parsed : [parsed];
      for (const node of nodes) {
        const graph = Array.isArray(node?.["@graph"]) ? node["@graph"] : [];
        const candidates = [node, ...graph];
        for (const item of candidates) {
          if (!isJobPostingType(item?.["@type"])) continue;
          const desc = item?.description;
          if (desc && String(desc).trim().length > 80) {
            return decodeHtml(stripTags(String(desc)));
          }
        }
      }
    } catch {
      // try next block
    }
  }
  return "";
};

const extractShowMoreMarkup = (html) => {
  const raw = String(html || "");
  const patterns = [
    /class="[^"]*show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /show-more-less-html__markup[^>]*>([\s\S]*?)<\/div>/i,
  ];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) {
      const text = decodeHtml(stripTags(match[1]));
      if (text.length >= MIN_FULL_JOB_TEXT) return text;
    }
  }
  return "";
};

const extractGuestDescriptionRich = (html) => {
  const raw = String(html || "");
  const patterns = [
    /class="[^"]*description__text[^"]*description__text--rich[^"]*"[^>]*>([\s\S]*?)<\/div>/i,
    /description__text--rich[^>]*>([\s\S]*?)<\/div>/i,
  ];
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]) {
      const text = decodeHtml(stripTags(match[1]));
      if (text.length >= MIN_FULL_JOB_TEXT) return text;
    }
  }
  return "";
};

const extractLinkedInDescription = (html) => {
  const jsonLd = extractJsonLdJobPostingDescription(html);
  if (jsonLd.length >= MIN_FULL_JOB_TEXT) return jsonLd;

  const showMore = extractShowMoreMarkup(html);
  if (showMore.length >= MIN_FULL_JOB_TEXT) return showMore;

  const guestRich = extractGuestDescriptionRich(html);
  if (guestRich.length >= MIN_FULL_JOB_TEXT) return guestRich;

  return decodeHtml(stripTags(html));
};

const looksLikeHardBlock = (html, text) => {
  const h = String(html || "").toLowerCase();
  const t = String(text || "").toLowerCase();
  if (h.includes("authwall")) return true;
  if (t.includes("sign in to linkedin")) return true;
  if (t.length < 80 && /login|authwall/.test(h)) return true;
  return false;
};

const CLOSED_POSTING_REJECT = "No longer accepting applications";

const isPostingClosedInRawGuestHtml = (html) => {
  const raw = String(html || "");
  if (!raw.trim()) return false;
  if (/closed-job__flavor--closed/i.test(raw)) return true;
  if (/no longer accepting applications/i.test(raw)) return true;
  return false;
};

const upstream = $("Normalize AI Evaluation").item?.json || {};
const jobId = String(upstream.JobId || $json.JobId || "").trim();
const statusCode = Number($json.statusCode || 0);
const html =
  typeof $json.data === "string"
    ? $json.data
    : typeof $json.body === "string"
      ? $json.body
      : typeof $json === "string"
        ? $json
        : "";

const postingClosedConfirmed =
  statusCode > 0 &&
  statusCode < 400 &&
  String(html).trim().length > 0 &&
  isPostingClosedInRawGuestHtml(html);

let enrichmentError = "";
let fullJobText = "";

if (!jobId && !String(upstream.URL || $json.URL || "").trim()) {
  enrichmentError = "Missing JobId and URL";
} else if (statusCode >= 400) {
  enrichmentError = `HTTP ${statusCode}`;
} else if (!String(html).trim()) {
  enrichmentError = "Empty response";
} else {
  fullJobText = extractLinkedInDescription(html).slice(0, MAX_FULL_JOB_TEXT);
  const stripped = stripTags(html);
  if (fullJobText.trim().length < MIN_FULL_JOB_TEXT) {
    enrichmentError = looksLikeHardBlock(html, stripped)
      ? "Auth wall / login page"
      : "No description block found";
  }
}

const enrichmentStatus =
  fullJobText.trim().length >= MIN_FULL_JOB_TEXT && !enrichmentError ? "OK" : "FAILED";

return {
  json: {
    ...upstream,
    FullJobText: fullJobText.trim(),
    FullJobTextLength: fullJobText.trim().length,
    EnrichmentStatus: enrichmentStatus,
    EnrichmentError: enrichmentStatus === "OK" ? "" : enrichmentError || "Extraction failed",
    PostingClosedConfirmed: postingClosedConfirmed,
    PostingClosedRejectReason: postingClosedConfirmed ? CLOSED_POSTING_REJECT : "",
  },
};

const MIN_FULL_JOB_TEXT = 200;
const TRAVEL_LIMIT = 20;

const TRAVEL_CTX = /\b(travel|travelling|traveling|on[- ]site|on the road)\b/i;
const SOFT_TRAVEL = /\b(occasional|optional|preferred|nice to have|highly desirable|desirable|a plus|ideally|willingness to|willing to)\b/i;
const MANDATORY_TRAVEL = /\b(required|as required|must|mandatory|essential|need to|expected to|will be required|minimum|at least)\b/i;

const parseTravelPercentMax = (chunk) => {
  const c = String(chunk || '').replace(/[–—]/g, '-');
  let m = c.match(/(\d{1,2})\s*-\s*(\d{1,2})\s*%/);
  if (m) {
    const lo = parseInt(m[1], 10);
    const hi = parseInt(m[2], 10);
    return { max: Math.max(lo, hi), label: `${lo}-${hi}%` };
  }
  m = c.match(/up\s+to\s+(\d{1,2})\s*%/i);
  if (m) return { max: parseInt(m[1], 10), label: `up to ${m[1]}%` };
  m = c.match(/(?:minimum|min(?:imum)?|at least)\s+(\d{1,2})\s*%/i);
  if (m) return { max: parseInt(m[1], 10), label: `minimum ${m[1]}%` };
  m = c.match(/(\d{1,2})\s*%\s*\+/i);
  if (m) return { max: parseInt(m[1], 10), label: `${m[1]}%+` };
  m = c.match(/(\d{1,2})\s*%/);
  if (m) return { max: parseInt(m[1], 10), label: `${m[1]}%` };
  return null;
};

const isExplicitMandatoryTravel = (chunk) => {
  if (MANDATORY_TRAVEL.test(chunk)) return true;
  if (/\d{1,2}\s*%\+?\s*travel/i.test(chunk)) return true;
  if (/\btravel\b[^.]{0,80}\b(required|as required|mandatory|must)\b/i.test(chunk)) return true;
  if (/\b(required|as required|mandatory|must|minimum|at least)\b[^.]{0,80}\btravel\b/i.test(chunk)) return true;
  return false;
};

const detectMandatoryTravelBlock = (fullJobText) => {
  const text = String(fullJobText || '').trim();
  if (text.length < MIN_FULL_JOB_TEXT) return { blocked: false, reason: '', percentMax: '' };

  const chunks = text.split(/[.;\n]/).map((c) => c.trim()).filter((c) => c.length >= 10);
  for (const chunk of chunks) {
    if (!TRAVEL_CTX.test(chunk)) continue;
    if (/\b(?:travel|travelling|traveling)\b[^.]{0,100}\bmay\s+be\s+required\b/i.test(chunk)) continue;

    const parsed = parseTravelPercentMax(chunk);
    if (!parsed) continue;
    if (parsed.max <= TRAVEL_LIMIT) continue;
    if (SOFT_TRAVEL.test(chunk) && !isExplicitMandatoryTravel(chunk)) continue;
    if (!isExplicitMandatoryTravel(chunk)) continue;

    return {
      blocked: true,
      reason: `Mandatory travel above 20%: ${parsed.label}`,
      percentMax: String(parsed.max),
    };
  }

  return { blocked: false, reason: '', percentMax: '' };
};

const fullJobText = String($json.FullJobText || '').trim();
const enrichmentOk =
  String($json.EnrichmentStatus || '') === 'OK' && fullJobText.length >= MIN_FULL_JOB_TEXT;
const block = enrichmentOk
  ? detectMandatoryTravelBlock(fullJobText)
  : { blocked: false, reason: '', percentMax: '' };

return {
  json: {
    ...$json,
    MandatoryTravelBlocked: block.blocked,
    MandatoryTravelRejectReason: block.reason || '',
    MandatoryTravelPercentMax: block.percentMax || '',
  },
};

const MIN_FULL_JOB_TEXT = 200;

const SOFT_PREFERENCE_ONLY = /\b(preferred|nice to have|highly desirable|desirable|advantageous|a plus|ideally|would be (?:a )?bonus)\b/i;

const DOMAIN_RULES = [
