      /\bclinical operations\b/i,
      /\bgcp\b/i,
      /\bich\b/i,
    ],
    label: 'clinical',
  },
  {
    domainPatterns: [
      /\bhome\s+care\b/i,
      /\bhealth\s*care\b/i,
      /\bhealthcare\b/i,
      /\belderly\s+care\b/i,
      /\bnursing\s+care\b/i,
      /\bhomecare\b/i,
    ],
    label: 'healthcare / home care',
  },
  {
    domainPatterns: [
      /\bregulated\s+financial\b/i,
      /\bbanking\s+regulatory\b/i,
      /\bpharma(?:ceutical)?\b/i,
      /\bmedtech\b/i,
    ],
    label: 'regulated financial / pharma',
  },
];

const hasMandatoryLanguage = (chunk) => {
  const c = String(chunk || '');
  if (!c.trim()) return false;
  if (SOFT_PREFERENCE_ONLY.test(c) && !/\b(mandatory|required|must have|must possess|essential)\b/i.test(c)) {
    return false;
  }
  return (
    /\b(is\s+)?mandatory\b/i.test(c)
    || /\b(required|must have|must possess|essential requirement|non-negotiable)\b/i.test(c)
    || (/\b(?:minimum|at least)\s+\d+\+?\s*years?\b/i.test(c) && /\b(?:experience|background|track record)\b/i.test(c))
    || /\d+\+?\s*years?[^.]{0,120}\b(?:is\s+)?(?:mandatory|required|essential)\b/i.test(c)
    || /\bproven\s+(?:senior\s+)?(?:leadership\s+)?experience\s+within\b/i.test(c)
  );
};

const hasSpecializedExperienceContext = (chunk) =>
  /\b(?:years?|experience|background|track record|prior|leading|expertise|proven|leadership)\b/i.test(chunk);

const detectMandatorySpecializedDomainBlock = (fullJobText) => {
  const text = String(fullJobText || '').trim();
  if (text.length < MIN_FULL_JOB_TEXT) return { blocked: false, reason: '', domain: '' };

  const chunks = text.split(/[.;\n]/).map((c) => c.trim()).filter((c) => c.length > 20);
  for (const chunk of chunks) {
    if (!hasMandatoryLanguage(chunk) || !hasSpecializedExperienceContext(chunk)) continue;

    for (const rule of DOMAIN_RULES) {
      if (rule.domainPatterns.some((re) => re.test(chunk))) {
        return {
          blocked: true,
          domain: rule.label,
          reason: `Mandatory specialized domain experience: ${rule.label}`,
        };
      }
    }
  }

  return { blocked: false, reason: '', domain: '' };
};

const fullJobText = String($json.FullJobText || '').trim();
const enrichmentOk =
  String($json.EnrichmentStatus || '') === 'OK' && fullJobText.length >= MIN_FULL_JOB_TEXT;
const block = enrichmentOk
  ? detectMandatorySpecializedDomainBlock(fullJobText)
  : { blocked: false, reason: '', domain: '' };

return {
  json: {
    ...$json,
    MandatoryDomainBlocked: block.blocked,
    MandatoryDomainRejectReason: block.reason || '',
    MandatoryDomainLabel: block.domain || '',
  },
};

// Skip HTTP enrichment when URL/JobUrl is missing or invalid. Keep preview/initial eval only.
const previewScore = Number($json.PreviewScore);
const threshold = Number($json.PreviewScoreThreshold ?? 7);
const passesPreview =
  $json.PreviewPassesThreshold === true
  || (Number.isFinite(previewScore) && previewScore >= threshold);

return {
  json: {
    ...$json,
    PipelineStage: 'NO_URL_PREVIEW_ONLY',
    NeedsEnrichment: false,
    MainRisk: 'Missing job URL; evaluated from email preview only',
    Status: passesPreview ? 'New' : 'Rejected',
    FinalDecision: passesPreview ? 'MONITOR' : 'REJECT_PREVIEW',
    RejectReason: passesPreview ? '' : ($json.RejectReason || 'Preview score below threshold (no URL)'),
    EnrichmentStatus: 'SKIPPED',
    EnrichmentError: 'Missing or invalid job URL; full posting fetch skipped',
    FullJobText: '',
    FullJobTextLength: 0,
    VerifiedScore: '',
    VerifiedRecommendation: '',
    VerifiedRisk: '',
    VerifiedWhyApply: '',
    FinalCV: '',
    VerifiedInterviewProbability: $json.InterviewProbability ?? $json.VerifiedInterviewProbability ?? 0,
    SalaryEstimate: '',
    SalaryTarget: '',
    SalaryConfidence: '',
    SalaryAssumption: '',
    VerifiedPriority: $json.VerifiedPriority || $json.Priority || 'LOW',
    SalaryRange: '',
  },
};
